final class Payment: Model {                 // base table
    static let schema = "payments"
    @ID(key: .id) var id: UUID?
    @Field(key: "name") var name: String
    @Field(key: "kind") var kind: String     // discriminator for STI-shaped tables
}
final class CardPayment: Model {             // class-table shape
    static let schema = "card_payments"
    @ID(key: .id) var id: UUID?
    @Parent(key: "payment_id") var payment: Payment    // join to the base row
    @Field(key: "card_number") var cardNumber: String
}
